{
  "contentId": "closeness.hadith.01",
  "language": "vi",
  "reading": {
    "title": "Cầu xin nhiều khi phủ phục",
    "quote_label": "Hadith",
    "quoted_sections": [
      {
        "text": "Ông Abu Huroiroh thuật lại lời Thiên Sứ của Allah ﷺ: {Khoảng cách gần nhất của người bề tôi với Allah là lúc y Sujud, vì vậy, các ngươi hãy cầu nguyện thật nhiều (trong Sujud).}"
      }
    ],
    "reader_credit": "Muslim, tuyển tập Sahih, số 482.",
    "explanation_label": "Giải thích riêng để hiểu rõ",
    "explanation_paragraphs": [
      "Sujud là phủ phục trong lễ nguyện: người thờ phượng đặt phần cao quý nhất của cơ thể xuống đất, biểu lộ sự vâng phục và khiêm nhường trước Allah. Lời cầu xin trong tư thế ấy kết hợp sự hạ mình bằng hành động với lời nói. Sự gần gũi được nói đến trong bối cảnh vâng lời và thờ phượng; đây là lúc được khuyến khích tăng lời cầu xin và hy vọng sự đáp lại."
    ],
    "published_context_label": "Lời giải thích nguyên văn trong bản xuất bản",
    "published_context": [
      {
        "text": "Nabi ﷺ cho biết rằng khoảng cách mà người bề tôi gần gũi nhất với Thượng Đế của mình là khi đang Sujud (cúi đầu quỳ lạy trong lễ nguyện Salah). Điều này là do người thờ phượng đặt phần cao nhất và cao quý nhất của cơ thể mình xuống đất để phục tùng, khiêm tốn và hạ mình trước Allah Toàn năng trong khi Sujud.\r\n\r\nThiên Sứ của Allah ﷺ đã bảo hãy nhiều lời cầu xin trong lúc Sujud, để kết hợp giữa lời nói và việc làm trong sự hạ mình vì Allah."
      }
    ],
    "required_published_notes_label": "Các bài học nguyên văn trong bản xuất bản",
    "required_published_notes": [
      {
        "text": "Sự vâng lời đưa người bề tôi đến gần AllahToàn Năng hơn.\r",
        "anchor": "1"
      },
      {
        "text": "Khuyến khích nhiều lời cầu xin trong Sujud, bởi vì nó là một trong những thời điểm mà lời cầu xin được đáp lại.",
        "anchor": "2"
      }
